UPDATE wcc_penalty_records p
JOIN wcc_transactions t ON t.id=p.transaction_id
SET p.student_id=t.student_id,p.student_name=t.student_name,p.equipment_name=t.equipment_name
WHERE t.metadata_json LIKE '%WCC_SEED_OCT_2026%';

UPDATE wcc_transaction_logs l
JOIN wcc_transactions t ON t.id=l.transaction_id
SET l.actor=t.student_name,l.detail=CONCAT('Synthetic seed request for ',t.equipment_name,'; batch WCC_SEED_OCT_2026')
WHERE l.event='Request Submitted'
  AND t.metadata_json LIKE '%WCC_SEED_OCT_2026%';

COMMIT;



-- Verification: expected 200 generated transaction IDs per day; 2,800 total.

SELECT DATE_FORMAT(`request_date`, '%Y-%m-%d') AS `seed_day`, COUNT(*) AS `transaction_records`, SUM(`status`='Pending') AS `pending`, SUM(`status`='Rejected') AS `rejected`, ROUND(100*SUM(`status`='Rejected')/COUNT(*),2) AS `rejection_percent`, SUM(`status`='Returned') AS `returned`, SUM(`status`='Approved') AS `approved`, SUM(`status`='Missing') AS `missing` FROM `wcc_transactions` WHERE `id` LIKE 'SD%' AND `request_date` BETWEEN '2026-10-01' AND '2026-10-14' GROUP BY `request_date` ORDER BY `request_date`;

SELECT COUNT(*) AS `total_seed_transactions` FROM `wcc_transactions` WHERE `id` LIKE 'SD%' AND `request_date` BETWEEN '2026-10-01' AND '2026-10-14';

SELECT `status`, COUNT(*) AS `records`, ROUND(100*COUNT(*)/(SELECT COUNT(*) FROM `wcc_transactions` WHERE `id` LIKE 'SD%' AND `request_date` BETWEEN '2026-10-01' AND '2026-10-14'),2) AS `percentage` FROM `wcc_transactions` WHERE `id` LIKE 'SD%' AND `request_date` BETWEEN '2026-10-01' AND '2026-10-14' GROUP BY `status` ORDER BY `status`;

-- Note: this seed inserts/reconciles only tagged transaction history and linked logs/penalties. It does not change equipment stock counters or non-seed records.
